use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::{fs, io::Read, path::{Component, Path, PathBuf}, process::Command, sync::{Mutex, OnceLock}, time::{SystemTime, UNIX_EPOCH}};
use tauri::Emitter;

const BUNDLE_VERSION: &str = "electron-44.8.0-nsis-3.0.4.1";
const ARCHIVE_SHA256: &str = "ec98edf5f02b581477e9065be584147acfd27a9880260e548d3a45d764aaef66";
const DEFAULT_EXPORT_URL: &str = "https://github.com/Xacur/RPGAtlas/releases/download/electron-export-44.8.0-nsis-3.0.4.1/rpgatlas-electron-export-electron-44.8.0-nsis-3.0.4.1.tar.gz";
static INSTALL_LOCK: OnceLock<Mutex<()>> = OnceLock::new();
#[derive(Deserialize)] struct Manifest { #[serde(rename="bundleVersion")] bundle_version: String, files: Vec<FileEntry> }
#[derive(Deserialize)] struct FileEntry { path: String, bytes: u64, sha256: String }
fn cache_dir() -> PathBuf { if let Ok(p)=std::env::var("RPGATLAS_EXPORT_CACHE"){return PathBuf::from(p)} dirs_next::cache_dir().unwrap_or_else(std::env::temp_dir).join("RPGAtlas").join(BUNDLE_VERSION) }
fn safe_name(s:&str)->String { let x:String=s.chars().map(|c|if c.is_ascii_alphanumeric()||c=='-'||c=='_'||c==' '{c}else{'_'}).collect(); if x.trim().is_empty(){"RPGAtlas_Game".into()}else{x.trim().replace(' ',"_")} }
fn emit(app:&tauri::AppHandle,stage:&str,message:&str,received:u64,total:Option<u64>){let _=app.emit("rpgatlas://electron-export-progress",serde_json::json!({"stage":stage,"message":message,"received":received,"total":total}));}
fn verify(root:&Path)->Result<Manifest,String>{let mp=root.join("manifest.json");let m:Manifest=serde_json::from_slice(&fs::read(&mp).map_err(|e|format!("Read manifest '{}': {e}",mp.display()))?).map_err(|e|format!("Parse manifest: {e}"))?;if m.bundle_version!=BUNDLE_VERSION{return Err(format!("Unsupported bundle version: {}",m.bundle_version))}for f in &m.files{let p=Path::new(&f.path);if p.is_absolute()||p.components().any(|c|matches!(c,Component::ParentDir)){return Err(format!("Unsafe resource path: {}",f.path))}let q=root.join(p);let d=fs::read(&q).map_err(|e|format!("Read resource '{}': {e}",q.display()))?;if d.len()as u64!=f.bytes{return Err(format!("Resource size mismatch: {}",f.path))}if format!("{:x}",Sha256::digest(&d))!=f.sha256{return Err(format!("Resource checksum mismatch: {}",f.path))}}Ok(m)}
fn ensure_bundle(app:&tauri::AppHandle)->Result<PathBuf,String>{let root=cache_dir();if root.join("manifest.json").exists(){emit(app,"checking","Using cached Windows export components",0,None);verify(&root)?;return Ok(root)}let _lock=INSTALL_LOCK.get_or_init(||Mutex::new(())).lock().map_err(|_|"Resource installer lock poisoned".to_string())?;if root.join("manifest.json").exists(){verify(&root)?;return Ok(root)}let url=std::env::var("RPGATLAS_EXPORT_URL").unwrap_or_else(|_| DEFAULT_EXPORT_URL.to_string());if !url.starts_with("https://")&&!url.starts_with("http://localhost")&&!url.starts_with("http://127.0.0.1"){return Err("Export resource URL must use HTTPS, or HTTP localhost for testing".into())}emit(app,"downloading","Downloading Windows export components (one-time)",0,None);let mut r=reqwest::blocking::get(&url).map_err(|e|format!("Download export components: {e}"))?;if !r.status().is_success(){return Err(format!("Download returned {}",r.status()))}let total=r.content_length();let stamp=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis();let tmp=std::env::temp_dir().join(format!("rpgatlas-components-{stamp}"));fs::create_dir_all(&tmp).map_err(|e|format!("Create download temp: {e}"))?;let part=tmp.join("bundle.tar.gz.part");let mut out=fs::File::create(&part).map_err(|e|format!("Create partial download '{}': {e}",part.display()))?;let mut hasher=Sha256::new();let mut buf=[0u8;65536];let mut got=0u64;loop{let n=r.read(&mut buf).map_err(|e|format!("Read download: {e}"))?;if n==0{break}use std::io::Write;out.write_all(&buf[..n]).map_err(|e|format!("Write partial download: {e}"))?;hasher.update(&buf[..n]);got+=n as u64;emit(app,"downloading","Downloading Windows export components",got,total)}out.sync_all().map_err(|e|format!("Flush download: {e}"))?;if format!("{:x}",hasher.finalize())!=ARCHIVE_SHA256{return Err("Export component archive checksum mismatch".into())}emit(app,"verifying","Verifying downloaded export components",got,total);let file=fs::File::open(&part).map_err(|e|format!("Open archive: {e}"))?;let dec=flate2::read::GzDecoder::new(file);let mut ar=tar::Archive::new(dec);let extracted=tmp.join("extracted");fs::create_dir_all(&extracted).map_err(|e|format!("Create extraction directory: {e}"))?;for e in ar.entries().map_err(|e|format!("Read archive entries: {e}"))?{let mut e=e.map_err(|e|format!("Read archive entry: {e}"))?;let p=e.path().map_err(|e|format!("Read archive path: {e}"))?.into_owned();if p.is_absolute()||p.components().any(|c|matches!(c,Component::ParentDir)){return Err(format!("Unsafe archive path: {}",p.display()))}if e.header().entry_type().is_symlink()||e.header().entry_type().is_hard_link(){return Err(format!("Archive links are not allowed: {}",p.display()))}e.unpack(extracted.join(&p)).map_err(|e|format!("Extract archive entry '{}': {e}", p.display()))?;}let extracted_root=extracted.join(BUNDLE_VERSION);verify(&extracted_root)?;if let Some(parent)=root.parent(){fs::create_dir_all(parent).map_err(|e|format!("Create cache parent: {e}"))?}let staging=root.with_extension("installing");let _=fs::remove_dir_all(&staging);fs::rename(&extracted_root,&staging).map_err(|e|format!("Stage export components: {e}"))?;let _=fs::remove_dir_all(&root);fs::rename(&staging,&root).map_err(|e|format!("Install export components: {e}"))?;let _=fs::remove_dir_all(&tmp);verify(&root)?;emit(app,"installed","Export components installed",0,None);Ok(root)}
pub fn package_windows_game(app:&tauri::AppHandle,project_json:String,html:String,destination:String)->Result<(),String>{let project:serde_json::Value=serde_json::from_str(&project_json).map_err(|e|format!("Parse project JSON: {e}"))?;let base=safe_name(project["system"]["title"].as_str().unwrap_or("RPGAtlas Game"));let root=ensure_bundle(app)?;emit(app,"packaging","Building Windows executable",0,None);let stamp=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis();let tmp=std::env::temp_dir().join(format!("rpgatlas-export-{stamp}"));let game=tmp.join("resources/game");copy_dir(&root.join("electron/win-unpacked"),&tmp)?;fs::create_dir_all(&game).map_err(|e|format!("Create payload directory: {e}"))?;fs::write(game.join("game.html"),html).map_err(|e|format!("Write game HTML: {e}"))?;fs::write(game.join("project.json"),project_json).map_err(|e|format!("Write project JSON: {e}"))?;let runner=fs::read_dir(&tmp).map_err(|e|format!("Read temp runner: {e}"))?.filter_map(Result::ok).find(|e|e.path().extension().and_then(|x|x.to_str()).map(|x|x.eq_ignore_ascii_case("exe")).unwrap_or(false)&&e.file_name()!="elevate.exe").ok_or("Runner executable missing")?;let nsi=tmp.join("portable.nsi");let pattern=tmp.to_string_lossy().replace('/',"\\");let output=PathBuf::from(&destination).to_string_lossy().replace('/',"\\");let script=format!("Unicode true\nRequestExecutionLevel user\nName \"{base}\"\nOutFile \"{output}\"\nSilentInstall silent\nAutoCloseWindow true\nFunction .onInit\nInitPluginsDir\nSetOutPath \"$PLUGINSDIR\\\\Game\"\nFile /r \"{pattern}\\\\*.*\"\nFunctionEnd\nSection\nSetOutPath \"$PLUGINSDIR\\\\Game\"\nExecWait '\"$PLUGINSDIR\\\\Game\\\\{base}.exe\"'\nSectionEnd\nFunction .onInstSuccess\nRMDir /r \"$PLUGINSDIR\\\\Game\"\nFunctionEnd\n");fs::rename(runner.path(),tmp.join(format!("{base}.exe"))).map_err(|e|format!("Rename runner: {e}"))?;fs::write(&nsi,script).map_err(|e|format!("Write NSIS script '{}': {e}",nsi.display()))?;let compiler=if cfg!(windows){root.join("nsis/Bin/makensis.exe")}else{root.join("nsis/linux/makensis")};if !compiler.is_file(){return Err(format!("NSIS compiler missing: {}",compiler.display()))}let out=Command::new(&compiler).arg(&nsi).env("NSISDIR",root.join("nsis")).current_dir(&root).output().map_err(|e|format!("Launch NSIS '{}': {e}",compiler.display()))?;if !out.status.success(){return Err(format!("NSIS failed: {}\nstdout:\n{}\nstderr:\n{}",out.status,String::from_utf8_lossy(&out.stdout),String::from_utf8_lossy(&out.stderr)))}if !Path::new(&destination).is_file(){return Err(format!("NSIS completed but output is missing: {destination}"))}fs::remove_dir_all(&tmp).map_err(|e|format!("Cleanup packaging temp: {e}"))?;emit(app,"complete","Export complete",0,None);Ok(())}
fn copy_dir(src:&Path,dst:&Path)->Result<(),String>{fs::create_dir_all(dst).map_err(|e|format!("Create '{}': {e}",dst.display()))?;for e in fs::read_dir(src).map_err(|e|format!("Read '{}': {e}",src.display()))?{let e=e.map_err(|e|format!("Read entry '{}': {e}",src.display()))?;let d=dst.join(e.file_name());let entry_path=e.path();if e.file_type().map_err(|err|format!("Inspect '{}': {err}",entry_path.display()))?.is_dir(){copy_dir(&entry_path,&d)?}else{fs::copy(&entry_path,&d).map_err(|e|format!("Copy '{}': {e}",d.display()))?;}}Ok(())}
